#include <stdio.h>


int main(void)
{
    int a = 48, b = 18;
    while (b) {
        int r = a % b;
        a = b; b = r;
    }
    printf("%d\n", a);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int x = -7, m = 11;
    printf("%d\n", (x % m + m) % m);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int composite[11] = {1, 1};
    for (int p = 2; p <= 10 / p; p++) {
        if (!composite[p]) {
            for (int k = p * p; k <= 10; k += p) {
                composite[k] = 1;
            }
        }
    }
    int count = 0;
    for (int k = 2; k <= 10; k++) {
        count += !composite[k];
    }
    printf("%d\n", count);
    return 0;
}
